import { createRouter } from "./router.js";
import { createModalManager } from "./modal-manager.js";
import { NAV_ITEMS, BLOCK_LABELS, actionById, blockById, esc, fmtDate, fmtDateTime, parseRoute, statusLabel, titleCase, typeLabel } from "./helpers.js";
import { renderHomeView } from "./home-view.js";
import { renderActionsView, renderActionDetailView, renderActionEditView } from "./actions-view.js";
import { renderBlocksView, renderBlockDetailView, renderBlockEditView } from "./blocks-view.js";
import { renderCyclesView } from "./cycles-view.js";
import { renderActionListsView } from "./action-lists-view.js";
import { renderProjectsView } from "./projects-view.js";
import { renderReviewsView } from "./reviews-view.js";
import { renderAnalysisView } from "./analysis-view.js";
import { renderHistoryView } from "./history-view.js";
import { renderSettingsView } from "./settings-view.js";
import { serializePackage } from "../import-export/exporter.js";

const APP_NAME = "SAMT";

function shell({ route, state, content, flash = null }) {
  const active = route.section === "blocks" && route.query.type === "cycle" ? "cycles" : route.section;
  const storageNotice = state.__storageAvailable === false ? `<div class="samt-notice warning" role="status"><strong>Memory mode.</strong> Browser storage is unavailable, so SAMT is still open and usable. Export a backup before closing this tab.</div>` : "";
  const migrationNotice = state.meta?.migratedFrom || state.legacy?.sourceSchemaVersion ? `<div class="samt-notice info" role="status">Your existing data is available in V3. Original source data remains preserved in migration metadata.</div>` : "";
  return `<div class="samt-app"><aside class="samt-sidebar"><a class="samt-brand" href="#/home"><span class="samt-brand-mark">↗</span><span><strong>${APP_NAME}</strong><small>direction · bearing · course</small></span></a><nav class="samt-nav" aria-label="Main navigation">${NAV_ITEMS.map(([key, label, icon]) => `<a class="samt-nav-item ${active === key ? "active" : ""}" href="#/${key}"><span class="samt-nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join("")}</nav><div class="samt-sidebar-foot"><button class="samt-button ghost full" data-action="open-log">＋ Quick log</button><small>Engine ${esc(state.schemaVersion || "3.0.0")}</small></div></aside><div class="samt-main"><header class="samt-mobile-head"><a class="samt-brand" href="#/home"><span class="samt-brand-mark">↗</span><strong>SAMT</strong></a><button class="samt-button ghost small" data-action="toggle-theme">Theme</button></header><main class="samt-content">${storageNotice}${migrationNotice}${flash ? `<div class="samt-notice ${esc(flash.level || "success")}" role="status">${esc(flash.message)}</div>` : ""}${content}</main><footer class="samt-footer"><span>SAMT engine · one factual event, one Action Log</span><a href="#/settings">Settings</a></footer></div></div>`;
}

function capacityView(state) {
  const capacity = state.settings?.capacity || {}; const logs = state.actionLogs || []; const total = logs.reduce((sum, log) => sum + Number(log.durationMinutes || 0), 0); const available = Number(capacity.availableMinutes || 0); const usedPercent = available > 0 ? Math.min(100, total / available * 100) : 0; return `<section class="samt-page" aria-labelledby="capacity-title"><header class="samt-page-head"><div><p class="samt-eyebrow">Planning without punishment</p><h1 id="capacity-title">Capacity</h1><p class="samt-muted">Capacity is a planning view over factual time, not a score or a streak.</p></div><a class="samt-button ghost" href="#/settings">Edit capacity</a></header><div class="samt-stat-grid"><article class="samt-card"><span class="samt-eyebrow">Available</span><strong class="samt-stat-value">${Math.round(available / 60 * 100) / 100}h</strong><small>${capacity.periodDays || 7}-day planning window</small></article><article class="samt-card"><span class="samt-eyebrow">Logged</span><strong class="samt-stat-value">${Math.round(total / 60 * 100) / 100}h</strong><small>Unique factual Action Logs</small></article><article class="samt-card"><span class="samt-eyebrow">Used</span><strong class="samt-stat-value">${available ? `${Math.round(usedPercent)}%` : "—"}</strong><small>Derived, never persisted as truth</small></article></div><article class="samt-card"><h2>Recent productive logs</h2><div class="samt-list">${logs.slice().sort((a, b) => new Date(b.eventAt) - new Date(a.eventAt)).slice(0, 20).map((log) => `<div class="samt-list-row"><div><strong>${esc(log.actionSnapshot?.name || log.actionId)}</strong><small>${esc(fmtDateTime(log.eventAt))}</small></div><b>${Math.round(Number(log.durationMinutes || 0))}m</b></div>`).join("") || `<p class="samt-empty">No factual time logged yet.</p>`}</div></article></section>`;
}

function resultInputs(action, units = []) {
  return (action?.resultFields || []).map((field) => {
    const config = field.config || {}; const required = field.required ? "required" : ""; let input = "";
    if (field.type === "percentage") input = `<input class="samt-input" name="result_${esc(field.id)}" type="number" min="0" max="100" step="any" ${required}>`;
    else if (field.type === "score") input = `<input class="samt-input" name="result_${esc(field.id)}" type="number" min="0" max="${esc(String(config.maximum ?? 100))}" step="any" ${required}>`;
    else if (field.type === "measurement") {
      const unitIds = (config.allowedUnitIds?.length ? config.allowedUnitIds : [config.defaultUnitId]).filter(Boolean);
      input = `<div class="samt-input-group"><input class="samt-input" name="result_${esc(field.id)}" type="number" step="any" ${required}><select class="samt-input" name="unit_${esc(field.id)}" ${unitIds.length ? "" : "disabled"}>${unitIds.map((id) => { const unit = units.find((candidate) => candidate.id === id); return `<option value="${esc(id)}">${esc(unit?.symbol || id)}</option>`; }).join("")}</select></div>`;
    } else if (field.type === "text") input = config.multiline ? `<textarea class="samt-input" name="result_${esc(field.id)}" rows="${config.displaySize === "large" ? 5 : config.displaySize === "small" ? 2 : 3}" minlength="${Number(config.minChars || 0)}" maxlength="${Number(config.maxChars || 2000)}" placeholder="${esc(config.placeholder || "")}" ${required}></textarea>` : `<input class="samt-input" name="result_${esc(field.id)}" minlength="${Number(config.minChars || 0)}" maxlength="${Number(config.maxChars || 2000)}" placeholder="${esc(config.placeholder || "")}" ${required}>`;
    else {
      const multiple = config.mode === "multiple"; const selectionLimits = multiple ? ` ${config.maxSelections != null ? `size="${Math.max(2, Number(config.maxSelections))}"` : `size="4"`}` : "";
      input = `<select class="samt-input" name="result_${esc(field.id)}" ${multiple ? "multiple" : ""}${selectionLimits} ${required && !multiple ? required : ""}>${multiple ? "" : "<option value=\"\">Choose…</option>"}${(config.options || []).slice().sort((a, b) => a.position - b.position).map((option) => `<option value="${esc(option.id)}">${esc(option.label)}</option>`).join("")}</select>`;
    }
    return `<label class="samt-result-input"><span>${esc(field.label)}${field.required ? " *" : ""}</span>${input}</label>`;
  }).join("");
}

function parseLogValues(form, action) {
  const data = new FormData(form); return (action?.resultFields || []).map((field) => {
    const config = field.config || {}; const multiple = field.type === "choice" && config.mode === "multiple"; const raw = multiple ? data.getAll(`result_${field.id}`) : data.get(`result_${field.id}`);
    if (raw == null || raw === "" || Array.isArray(raw) && raw.length === 0) return null;
    const value = field.type === "measurement" ? { value: Number(raw), unitId: data.get(`unit_${field.id}`) || field.config?.defaultUnitId } : field.type === "percentage" || field.type === "score" ? Number(raw) : raw;
    return { fieldId: field.id, value };
  }).filter(Boolean);
}

function resultConfigFields(type, state = {}, existing = {}) {
  const config = existing.config || {};
  if (type === "percentage") return `<label class="samt-check"><input type="checkbox" name="decimal" ${config.decimal ? "checked" : ""}> Allow decimals</label>`;
  if (type === "score") return `<div class="samt-form-grid"><label>Maximum<input class="samt-input" name="maximum" type="number" min="0" step="any" value="${esc(String(config.maximum ?? 100))}"></label><label class="samt-check"><input type="checkbox" name="decimal" ${config.decimal ? "checked" : ""}> Allow decimals</label></div>`;
  if (type === "measurement") return `<div class="samt-form-grid"><label>Default Unit<select class="samt-input" name="unitId"><option value="">Choose a Unit</option>${(state.units || []).filter((unit) => unit.status !== "archived").map((unit) => `<option value="${esc(unit.id)}" ${config.defaultUnitId === unit.id ? "selected" : ""}>${esc(unit.name)} (${esc(unit.symbol)})</option>`).join("")}</select></label><label>Minimum<input class="samt-input" name="min" type="number" step="any" value="${config.min == null ? "" : esc(String(config.min))}"></label><label>Maximum<input class="samt-input" name="max" type="number" step="any" value="${config.max == null ? "" : esc(String(config.max))}"></label></div><p class="samt-muted">Allowed Units follow the default Unit. Compatible conversions are validated by the engine.</p>`;
  if (type === "text") return `<div class="samt-form-grid"><label>Display size<select class="samt-input" name="displaySize">${["small", "medium", "large"].map((item) => `<option value="${item}" ${(config.displaySize || "medium") === item ? "selected" : ""}>${titleCase(item)}</option>`).join("")}</select></label><label class="samt-check"><input type="checkbox" name="multiline" ${config.multiline ? "checked" : ""}> Multiline</label><label>Placeholder<input class="samt-input" name="placeholder" value="${esc(config.placeholder || "")}"></label><label>Minimum characters<input class="samt-input" name="minChars" type="number" min="0" value="${Number(config.minChars || 0)}"></label><label>Maximum characters<input class="samt-input" name="maxChars" type="number" min="1" value="${Number(config.maxChars || 2000)}"></label></div>`;
  if (type === "choice") {
    const options = (config.options || []).slice().sort((a, b) => a.position - b.position).map((option) => option.label).join("\n");
    return `<label>Options (one per line)<textarea class="samt-input" name="options" rows="5" placeholder="Very good\nGood\nNeutral\nBad">${esc(options)}</textarea><div class="samt-form-grid"><label>Selection<select class="samt-input" name="mode"><option value="single" ${config.mode !== "multiple" ? "selected" : ""}>Single choice</option><option value="multiple" ${config.mode === "multiple" ? "selected" : ""}>Multiple choice</option></select></label><label>Minimum selections<input class="samt-input" name="minSelections" type="number" min="0" step="1" value="${Number(config.minSelections || 0)}"></label><label>Maximum selections<input class="samt-input" name="maxSelections" type="number" min="0" step="1" value="${config.maxSelections == null ? "" : Number(config.maxSelections)}"></label><label>Analytical direction<select class="samt-input" name="betterDirection"><option value="none" ${config.betterDirection !== "higher" && config.betterDirection !== "lower" ? "selected" : ""}>None (unordered)</option><option value="higher" ${config.betterDirection === "higher" ? "selected" : ""}>Higher is better</option><option value="lower" ${config.betterDirection === "lower" ? "selected" : ""}>Lower is better</option></select></label><label class="samt-check"><input type="checkbox" name="orderMatters" ${config.orderMatters ? "checked" : ""}> Display order has ordinal meaning</label></div>`;
  }
  return "";
}

function parseResultFieldForm(form, type, existing = {}) {
  const data = new FormData(form); const config = {};
  if (type === "percentage") config.decimal = data.get("decimal") === "on";
  else if (type === "score") Object.assign(config, { maximum: Number(data.get("maximum") || 100), decimal: data.get("decimal") === "on" });
  else if (type === "measurement") Object.assign(config, { defaultUnitId: data.get("unitId") || null, allowedUnitIds: data.get("unitId") ? [data.get("unitId")] : [], min: data.get("min") === "" ? null : Number(data.get("min")), max: data.get("max") === "" ? null : Number(data.get("max")), decimal: true });
  else if (type === "text") Object.assign(config, { multiline: data.get("multiline") === "on", displaySize: data.get("displaySize") || "medium", placeholder: data.get("placeholder") || "", minChars: Number(data.get("minChars") || 0), maxChars: Number(data.get("maxChars") || 2000) });
  else if (type === "choice") {
    const oldOptions = (existing.config?.options || []).slice().sort((a, b) => a.position - b.position); const labels = String(data.get("options") || "").split("\n").map((label) => label.trim()).filter(Boolean);
    Object.assign(config, { mode: data.get("mode") === "multiple" ? "multiple" : "single", options: labels.map((label, index) => ({ id: oldOptions[index]?.id || `option_${index + 1}`, label, position: index, analysisScore: oldOptions[index]?.analysisScore ?? null })), minSelections: Number(data.get("minSelections") || 0), maxSelections: data.get("maxSelections") === "" ? null : Number(data.get("maxSelections")), orderMatters: data.get("orderMatters") === "on", betterDirection: ["higher", "lower", "none"].includes(data.get("betterDirection")) ? data.get("betterDirection") : "none" });
  }
  return config;
}

function actionOptions(state, selected = "") { return (state.actions || []).filter((action) => action.status !== "archived").map((action) => `<option value="${esc(action.id)}" ${selected === action.id ? "selected" : ""}>${esc(action.name)}${action.direction === "avoid" ? " · avoid" : ""}</option>`).join(""); }
function blockOptions(state, selected = "", exclude = null) { return (state.blocks || []).filter((block) => block.id !== exclude && block.definitionStatus !== "ARCHIVED").map((block) => `<option value="${esc(block.id)}" ${selected === block.id ? "selected" : ""}>${esc(block.name)} · ${esc(typeLabel(block.type))}</option>`).join(""); }

export function mountSamtApp(engine, documentRef = globalThis.document) {
  if (!documentRef?.body) return null;
  const root = documentRef.getElementById("app") || documentRef.body; const modal = createModalManager(documentRef); const windowRef = documentRef.defaultView || globalThis.window; let flash = null; let activeRoute = { section: "home", query: {} };
  const router = createRouter({ windowRef, onRoute: (path) => { activeRoute = parseRoute(path); render(); } });
  function stateForView() { const state = { ...engine.getState() }; state.__storageAvailable = engine.repository.storageAvailable?.(); return state; }
  function showFlash(message, level = "success") { flash = { message, level }; render(); windowRef?.setTimeout?.(() => { flash = null; render(); }, 3500); }
  function runCommand(callback, success = "Saved.") { try { callback(); showFlash(success); } catch (error) { showFlash(error?.message || "The command could not be completed.", "error"); } }
  function render() {
    const state = stateForView(); const route = activeRoute; let content = "";
    if (route.section === "home") content = renderHomeView({ model: engine.queries.getHomeViewModel({ timezone: state.settings?.timezone }), state });
    else if (route.section === "actions") { const action = route.id ? actionById(state, route.id) : null; content = route.id && route.mode === "edit" ? renderActionEditView({ state, action }) : route.id ? renderActionDetailView({ state, action }) : renderActionsView({ state, query: route.query }); }
    else if (route.section === "blocks") { const block = route.id ? blockById(state, route.id) : null; if (block?.type === "target") { try { state.__targetProgress = { [block.id]: engine.queries.getTargetProgress(block.id) }; } catch { state.__targetProgress = {}; } } content = route.id && route.mode === "edit" ? renderBlockEditView({ state, block }) : route.id ? renderBlockDetailView({ state, block }) : renderBlocksView({ state, filterType: route.query.type || "all" }); }
    else if (route.section === "cycles") content = renderCyclesView({ state });
    else if (route.section === "todo") content = renderActionListsView({ state });
    else if (route.section === "projects") content = renderProjectsView({ state });
    else if (route.section === "reviews") content = renderReviewsView({ state });
    else if (route.section === "analysis") { const model = engine.queries.getAnalysisViewModel({ blockId: route.query.blockId || null, actionId: route.query.actionId || null, from: route.query.from || null, to: route.query.to || null, resultFieldId: route.query.resultFieldId || null }); const targetProgress = {}; for (const block of state.blocks || []) if (block.type === "target") { try { targetProgress[block.id] = engine.queries.getTargetProgress(block.id); } catch { /* invalid/incomplete target definitions stay visible */ } } state.__targetProgress = targetProgress; content = renderAnalysisView({ model, state, filters: route.query }); }
    else if (route.section === "history") content = renderHistoryView({ state });
    else if (route.section === "capacity") content = capacityView(state);
    else if (route.section === "settings") content = renderSettingsView({ state });
    else content = `<section class="samt-page"><div class="samt-empty-state"><h1>Page not found</h1><a class="samt-button" href="#/home">Go Home</a></div></section>`;
    root.innerHTML = shell({ route, state, content, flash });
  }
  function openForm({ title, content, onSubmit, onChange = null }) {
    const dialog = modal.open({ title, content }); const form = dialog.element.querySelector("form"); if (!form) return dialog; form.addEventListener("submit", (event) => { event.preventDefault(); try { onSubmit(form, dialog.close); dialog.close(); render(); } catch (error) { const target = dialog.element.querySelector("[data-form-error]"); if (target) target.textContent = error?.message || "Could not save."; else showFlash(error?.message || "Could not save.", "error"); } }); if (onChange) form.addEventListener("change", (event) => onChange(event, form, dialog.element)); return dialog;
  }
  function openLogModal(actionId = null, context = {}) {
    const state = stateForView(); if (!(state.actions || []).length) { showFlash("Create an Action before logging progress.", "info"); router.navigate("/actions"); return; }
    const selected = actionId || state.actions.find((action) => action.status === "active")?.id || state.actions[0].id; const action = actionById(state, selected); const local = new Date(); local.setMinutes(local.getMinutes() - local.getTimezoneOffset()); const defaultTime = local.toISOString().slice(0, 16);
    openForm({ title: action?.direction === "avoid" ? "Log Avoid Action" : "Log Action", content: `<form class="samt-form" data-form="log-action"><p class="samt-muted">One real-world event creates one factual Action Log. Context attribution is optional.</p><label>Action<select class="samt-input" name="actionId" data-log-action>${actionOptions(state, selected)}</select></label><div data-result-fields>${resultInputs(action, state.units || [])}</div><div class="samt-form-grid"><label>Duration (minutes)<input class="samt-input" name="durationMinutes" type="number" min="0" step="any" value="0"></label><label>Quantity<input class="samt-input" name="quantity" type="number" min="0" step="any"></label><label>When<input class="samt-input" name="eventAt" type="datetime-local" value="${defaultTime}"></label></div><label>Note<textarea class="samt-input" name="note" rows="2" placeholder="Optional context"></textarea><input type="hidden" name="occurrenceId" value="${esc(context.occurrenceId || "")}"><input type="hidden" name="blockId" value="${esc(context.blockId || "")}"><p class="samt-form-error" data-form-error role="alert"></p><button class="samt-button primary" type="submit">Save factual log</button></form>`, onChange: (event, form, element) => { if (event.target.name !== "actionId") return; const next = actionById(state, event.target.value); element.querySelector("[data-result-fields]").innerHTML = resultInputs(next, state.units || []); }, onSubmit: (form) => { const data = new FormData(form); const currentAction = actionById(state, data.get("actionId")); if (!currentAction) throw new Error("Choose an Action."); const timestamp = data.get("eventAt") ? new Date(data.get("eventAt")).toISOString() : new Date().toISOString(); const refs = []; if (data.get("occurrenceId")) refs.push({ occurrenceId: data.get("occurrenceId") }); if (data.get("blockId")) refs.push({ blockId: data.get("blockId") }); engine.commands.logAction({ actionId: currentAction.id, eventAt: timestamp, durationMinutes: Number(data.get("durationMinutes") || 0), quantity: data.get("quantity") === "" ? null : Number(data.get("quantity")), resultValues: parseLogValues(form, currentAction), contextRefs: refs, note: data.get("note") || "", finalizing: true, commandId: `ui-log-${Date.now()}-${Math.random().toString(36).slice(2)}` }); flash = { message: "Action Log saved.", level: "success" }; } });
  }
  function openNewAction() {
    const state = stateForView(); openForm({ title: "New Action", content: `<form class="samt-form" data-form="new-action"><div class="samt-form-grid"><label>Name<input class="samt-input" name="name" required autofocus></label><label>Direction<select class="samt-input" name="direction"><option value="do">Do</option><option value="avoid">Avoid</option></select></label><label>Completion<select class="samt-input" name="completionMethod"><option value="time">Time minimum</option><option value="quantity">Quantity target</option></select></label><label>Minimum / target<input class="samt-input" name="completionValue" type="number" min="0" step="any" value="0"></label></div><label>Description<textarea class="samt-input" name="description" rows="3"></textarea></label><label>Tags<select class="samt-input" name="tagId" multiple size="4">${(state.tags || []).filter((tag) => tag.status !== "archived").map((tag) => `<option value="${esc(tag.id)}">${esc(tag.name)}</option>`).join("")}</select></label><p class="samt-muted">Add Result Fields after creating the Action. Up to 10 fields are supported.</p><p class="samt-form-error" data-form-error role="alert"></p><button class="samt-button primary" type="submit">Create Action</button></form>`, onSubmit: (form) => { const data = new FormData(form); const action = engine.commands.createAction({ name: data.get("name"), direction: data.get("direction"), description: data.get("description"), tagIds: data.getAll("tagId"), completion: data.get("completionMethod") === "quantity" ? { method: "quantity", target: Number(data.get("completionValue")) } : { method: "time", minimumMinutes: Number(data.get("completionValue")) } }); modal.close(); router.navigate(`/actions/${encodeURIComponent(action.id)}`); flash = { message: "Action created.", level: "success" }; } });
  }
  function blockConfigFromForm(form, type) {
    const data = new FormData(form); const config = {};
    if (type === "target") {
      const rawTarget = data.get("config.targetValue");
      Object.assign(config, { mode: data.get("config.mode"), metric: data.get("config.metric"), targetValue: data.get("config.mode") === "outcome" ? String(rawTarget || "") : Number(rawTarget || 0), comparison: data.get("config.comparison") || ">=", period: data.get("config.period"), periodStyle: data.get("config.periodStyle") || "calendar", contributionScope: data.get("config.contributionScope") || "direct", sourceActionIds: data.getAll("sourceActionId"), sourceResultFieldId: data.get("config.sourceResultFieldId") || null, aggregation: data.get("config.aggregation") || "latest", unitId: data.get("config.unitId") || null });
    } else if (type === "cycle") Object.assign(config, { generationMode: data.get("config.generationMode"), eligibility: data.get("config.eligibility"), smallCycleSize: data.get("config.smallCycleSize") ? Number(data.get("config.smallCycleSize")) : null, missedItemPolicy: data.get("config.missedItemPolicy") || "keep_position" });
    else if (type === "routine") Object.assign(config, { completionMode: data.get("config.completionMode"), minimumCount: Number(data.get("config.minimumCount") || 0), minimumPercentage: Number(data.get("config.minimumPercentage") || 100), finishBehaviour: data.get("config.finishBehaviour") || "auto" });
    else if (type === "project") Object.assign(config, { combination: data.get("config.combination"), finishBehaviour: data.get("config.finishBehaviour"), deadline: data.get("config.deadline") || null, conditions: [{ type: "all_required" }] });
    else if (type === "action_list") Object.assign(config, { occurrencePolicy: data.get("config.occurrencePolicy") });
    return config;
  }
  function newBlockContent(state, type = "collection") { return `<form class="samt-form" data-form="new-block"><div class="samt-form-grid"><label>Name<input class="samt-input" name="name" required autofocus></label><label>Type<select class="samt-input" name="type" data-block-type>${Object.entries(BLOCK_LABELS).map(([key, label]) => `<option value="${key}" ${type === key ? "selected" : ""}>${label}</option>`).join("")}</select></label><label>Definition status<select class="samt-input" name="definitionStatus"><option value="LIBRARY">Library</option><option value="ACTIVE" selected>Active</option><option value="PAUSED">Paused</option></select></label></div><label>Description<textarea class="samt-input" name="description" rows="3"></textarea></label><div data-block-config>${configFieldsForNew(type, state)}</div><p class="samt-form-error" data-form-error role="alert"></p><button class="samt-button primary" type="submit">Create Block</button></form>`; }
  function configFieldsForNew(type, state = {}) {
    if (type === "target") return `<fieldset><legend>Target configuration</legend><div class="samt-form-grid"><label>Mode<select class="samt-input" name="config.mode"><option value="accumulation">Accumulation</option><option value="outcome">Outcome</option></select></label><label>Metric<select class="samt-input" name="config.metric"><option value="time">Time</option><option value="quantity">Quantity</option><option value="completion_count">Completion count</option></select></label><label>Target value<input class="samt-input" name="config.targetValue" type="text" value="0"></label><label>Comparison<select class="samt-input" name="config.comparison">${[">=", ">", "=", "<=", "<"].map((item) => `<option value="${item}">${item}</option>`).join("")}</select></label><label>Period<select class="samt-input" name="config.period"><option value="day">Day</option><option value="week">Week</option><option value="month">Month</option><option value="all_time">All time</option></select></label><label>Period style<select class="samt-input" name="config.periodStyle"><option value="calendar">Calendar</option><option value="rolling">Rolling</option></select></label><label>Contribution<select class="samt-input" name="config.contributionScope"><option value="direct">Direct only</option><option value="inclusive">Inclusive unique descendants</option></select></label><label>Source Actions<select class="samt-input" name="sourceActionId" multiple size="4">${actionOptions(state)}</select></label><label>Outcome Result Field<select class="samt-input" name="config.sourceResultFieldId"><option value="">Choose for outcome Targets</option>${(state.actions || []).flatMap((action) => (action.resultFields || []).map((field) => `<option value="${esc(field.id)}">${esc(action.name)} · ${esc(field.label)}</option>`)).join("")}</select></label><label>Outcome aggregation<select class="samt-input" name="config.aggregation">${["latest", "highest", "lowest", "average"].map((item) => `<option value="${item}">${titleCase(item)}</option>`).join("")}</select></label><label>Unit ID (for measurements)<input class="samt-input" name="config.unitId" placeholder="Optional compatible Unit ID"></label></div></fieldset>`;
    if (type === "cycle") return `<fieldset><legend>Cycle configuration</legend><div class="samt-form-grid"><label>Generation<select class="samt-input" name="config.generationMode"><option value="simple_ordered">Simple ordered</option><option value="exact_frequency">Exact frequency</option><option value="weighted_limited">Weighted limited</option></select></label><label>Eligibility<select class="samt-input" name="config.eligibility"><option value="strict_order">Strict order</option><option value="next_eligible">Next eligible</option></select></label><label>Small Cycle slots<input class="samt-input" name="config.smallCycleSize" type="number" min="1" step="1"></label><label>Missed item policy<select class="samt-input" name="config.missedItemPolicy"><option value="keep_position">Keep position</option><option value="advance_to_next">Advance to next</option><option value="restart_small_cycle">Restart Small Cycle</option><option value="restart_big_cycle">Restart Big Cycle</option></select></label></div></fieldset>`;
    if (type === "routine") return `<fieldset><legend>Routine completion</legend><div class="samt-form-grid"><label>Mode<select class="samt-input" name="config.completionMode"><option value="required_only">Required only</option><option value="count">Count</option><option value="percentage">Percentage</option><option value="manual">Manual</option></select></label><label>Minimum count<input class="samt-input" name="config.minimumCount" type="number" min="0" step="1" value="0"></label><label>Minimum percentage<input class="samt-input" name="config.minimumPercentage" type="number" min="0" max="100" value="100"></label><label>Finish behaviour<select class="samt-input" name="config.finishBehaviour"><option value="auto">Auto finish</option><option value="ready">Ready to finish</option></select></label></div></fieldset>`;
    if (type === "project") return `<fieldset><legend>Project conditions</legend><div class="samt-form-grid"><label>Combination<select class="samt-input" name="config.combination"><option value="all">All conditions</option><option value="any">Any condition</option></select></label><label>Finish behaviour<select class="samt-input" name="config.finishBehaviour"><option value="ready">Ready to finish</option><option value="auto">Auto finish</option></select></label><label>Deadline<input class="samt-input" name="config.deadline" type="date"></label></div></fieldset>`;
    if (type === "action_list") return `<fieldset><legend>Action List</legend><label>Default unfinished policy<select class="samt-input" name="config.occurrencePolicy"><option value="expire">Expire</option><option value="carry_forward">Carry forward</option><option value="stay_overdue">Stay overdue</option></select></label></fieldset>`;
    return `<p class="samt-muted">Collections and Workflows use their relationships to define structure.</p>`;
  }
  function openNewBlock(type = "collection") { const state = stateForView(); openForm({ title: `New ${typeLabel(type)}`, content: newBlockContent(state, type), onChange: (event, form, element) => { if (event.target.name === "type") element.querySelector("[data-block-config]").innerHTML = configFieldsForNew(event.target.value, state); }, onSubmit: (form) => { const data = new FormData(form); const block = engine.commands.createBlock({ name: data.get("name"), type: data.get("type"), description: data.get("description"), definitionStatus: data.get("definitionStatus"), config: blockConfigFromForm(form, data.get("type")) }); modal.close(); router.navigate(`/blocks/${encodeURIComponent(block.id)}`); flash = { message: "Block created.", level: "success" }; } }); }
  function openResultModal(actionId, fieldId = null) {
    const state = stateForView(); const action = actionById(state, actionId); const existing = fieldId ? action?.resultFields?.find((field) => field.id === fieldId) : null; if (!action || fieldId && !existing) return;
    const selectedType = existing?.type || "percentage";
    openForm({ title: existing ? "Edit Result Field" : "Add Result Field", content: `<form class="samt-form" data-form="result-field"><div class="samt-form-grid"><label>Type<select class="samt-input" name="type"><option value="percentage" ${selectedType === "percentage" ? "selected" : ""}>Percentage</option><option value="score" ${selectedType === "score" ? "selected" : ""}>Score</option><option value="measurement" ${selectedType === "measurement" ? "selected" : ""}>Measurement</option><option value="text" ${selectedType === "text" ? "selected" : ""}>Text input</option><option value="choice" ${selectedType === "choice" ? "selected" : ""}>Choice</option></select></label><label>Label / question<input class="samt-input" name="label" value="${esc(existing?.label || "")}" required></label><label>Required<select class="samt-input" name="required"><option value="false" ${!existing?.required ? "selected" : ""}>Optional</option><option value="true" ${existing?.required ? "selected" : ""}>Required</option></select></label></div><div data-result-config>${resultConfigFields(selectedType, state, existing || {})}</div><p class="samt-muted">Result definitions are versioned. Historical logs keep their field snapshots.</p><p class="samt-form-error" data-form-error role="alert"></p><button class="samt-button primary" type="submit">${existing ? "Save Result" : "Add Result"}</button></form>`, onChange: (event, form, element) => { if (event.target.name === "type") element.querySelector("[data-result-config]").innerHTML = resultConfigFields(event.target.value, state, {}); }, onSubmit: (form) => { const data = new FormData(form); const type = data.get("type"); const patch = { type, label: data.get("label"), required: data.get("required") === "true", config: parseResultFieldForm(form, type, existing || {}) }; if (existing) engine.commands.updateResultField(actionId, fieldId, patch); else engine.commands.addResultField(actionId, patch); flash = { message: existing ? "Result Field updated." : "Result Field added.", level: "success" }; } });
  }
  function openRelationshipModal(blockId) { const state = stateForView(); const parent = blockById(state, blockId); if (!parent) return; const kind = parent.type === "collection" || parent.type === "project" || parent.type === "routine" || parent.type === "workflow" || parent.type === "action_list" || parent.type === "cycle" || parent.type === "target" ? "action" : "action"; openForm({ title: `Add relationship to ${parent.name}`, content: `<form class="samt-form" data-form="new-relationship"><div class="samt-form-grid"><label>Reference kind<select class="samt-input" name="kind"><option value="action">Action</option><option value="block">Block</option></select></label><label>Reference<select class="samt-input" name="refId" data-reference>${actionOptions(state)}</select></label><label>Context label<input class="samt-input" name="label" placeholder="Morning, Step 1…"></label><label>Position<input class="samt-input" name="position" type="number" min="0" step="1" value="${(parent.relationships || []).length}"></label></div><div class="samt-form-grid"><label class="samt-check"><input type="checkbox" name="required"> Required</label><label class="samt-check"><input type="checkbox" name="allowSkip"> Allow skip</label><label>Schedule<select class="samt-input" name="scheduleMode"><option value="manual">Manual</option><option value="always_available">Always available</option><option value="calendar">Calendar daily</option><option value="once">Once</option><option value="interval">Interval</option></select></label><label>Unfinished policy<select class="samt-input" name="unfinishedPolicy"><option value="expire">Expire</option><option value="carry_forward">Carry forward</option><option value="stay_overdue">Stay overdue</option></select></label></div><div data-schedule-fields></div><div data-cycle-fields>${parent.type === "cycle" ? `<div class="samt-form-grid"><label>Appearance<select class="samt-input" name="appearanceMode"><option value="fixed">Fixed</option><option value="weighted">Weighted</option></select></label><label>Fixed count<input class="samt-input" name="fixedCount" type="number" min="0" value="1"></label><label>Weight<input class="samt-input" name="weight" type="number" min="0.01" step="any" value="1"></label></div>` : ""}</div><p class="samt-form-error" data-form-error role="alert"></p><button class="samt-button primary" type="submit">Add relationship</button></form>`, onChange: (event, form, element) => { if (event.target.name === "kind") { const select = element.querySelector("[data-reference]"); select.innerHTML = event.target.value === "action" ? actionOptions(state) : blockOptions(state, "", blockId); } if (event.target.name === "scheduleMode") { const host = element.querySelector("[data-schedule-fields]"); host.innerHTML = event.target.value === "once" ? `<label>Date<input class="samt-input" name="scheduleDate" type="date" required></label>` : event.target.value === "interval" ? `<div class="samt-form-grid"><label>Every<input class="samt-input" name="every" type="number" min="1" value="1"></label><label>Unit<select class="samt-input" name="intervalUnit"><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option><option value="hours">Hours</option></select></label><label>Anchor<input class="samt-input" name="anchorAt" type="datetime-local"></label></div>` : ""; } }, onSubmit: (form) => { const data = new FormData(form); const mode = data.get("scheduleMode"); const schedule = mode === "manual" ? { mode } : mode === "always_available" ? { mode } : mode === "calendar" ? { mode, calendarKind: "daily", dateOnly: true } : mode === "once" ? { mode, date: data.get("scheduleDate"), dateOnly: true } : { mode, every: Number(data.get("every") || 1), unit: data.get("intervalUnit") || "days", anchorAt: data.get("anchorAt") ? new Date(data.get("anchorAt")).toISOString() : new Date().toISOString(), dateOnly: true }; const config = { required: data.get("required") === "on", allowSkip: data.get("allowSkip") === "on", unfinishedPolicy: data.get("unfinishedPolicy") || "expire", schedule }; if (parent.type === "cycle") Object.assign(config, { appearanceMode: data.get("appearanceMode"), fixedCount: Number(data.get("fixedCount") || 0), weight: Number(data.get("weight") || 1) }); engine.commands.addRelationship(blockId, { kind: data.get("kind"), refId: data.get("refId"), label: data.get("label") || null, position: Number(data.get("position") || 0), config }); try { engine.reconcile(); } catch { /* a malformed optional schedule must not block the definition */ } flash = { message: "Relationship added.", level: "success" }; } }); }
  function openCategoryModal() { openForm({ title: "New Category", content: `<form class="samt-form" data-form="new-category"><label>Name<input class="samt-input" name="name" required autofocus></label><label>Description<textarea class="samt-input" name="description" rows="2"></textarea></label><label>Scope<select class="samt-input" name="scope"><option value="both">Action + Result</option><option value="action">Action</option><option value="result">Result</option></select></label><p class="samt-form-error" data-form-error role="alert"></p><button class="samt-button primary" type="submit">Create Category</button></form>`, onSubmit: (form) => { const data = new FormData(form); engine.commands.createCategory({ name: data.get("name"), description: data.get("description"), scope: data.get("scope") }); flash = { message: "Category created.", level: "success" }; } }); }
  function openTagModal() { const state = stateForView(); if (!(state.categories || []).length) { showFlash("Create a Category first.", "info"); return; } openForm({ title: "New Tag", content: `<form class="samt-form" data-form="new-tag"><label>Category<select class="samt-input" name="categoryId">${(state.categories || []).filter((category) => category.status !== "archived").map((category) => `<option value="${esc(category.id)}">${esc(category.name)}</option>`).join("")}</select></label><label>Name<input class="samt-input" name="name" required></label><label>Scope<select class="samt-input" name="scope"><option value="both">Action + Result</option><option value="action">Action</option><option value="result">Result</option></select></label><button class="samt-button primary" type="submit">Create Tag</button></form>`, onSubmit: (form) => { const data = new FormData(form); engine.commands.createTag({ categoryId: data.get("categoryId"), name: data.get("name"), scope: data.get("scope") }); flash = { message: "Tag created.", level: "success" }; } }); }
  function openUnitModal() { openForm({ title: "New Custom Unit", content: `<form class="samt-form" data-form="new-unit"><div class="samt-form-grid"><label>Name<input class="samt-input" name="name" required></label><label>Symbol<input class="samt-input" name="symbol" required></label><label>Dimension<input class="samt-input" name="dimension" placeholder="mass, count:pages…" required></label><label>Factor to base<input class="samt-input" name="factor" type="number" min="0.000001" step="any" value="1" required></label><label>Decimal precision<input class="samt-input" name="decimalPrecision" type="number" min="0" max="10" value="2"></label></div><button class="samt-button primary" type="submit">Create Unit</button></form>`, onSubmit: (form) => { const data = new FormData(form); engine.commands.createUnit({ name: data.get("name"), symbol: data.get("symbol"), dimension: data.get("dimension"), factor: Number(data.get("factor")), decimalPrecision: Number(data.get("decimalPrecision")) }); flash = { message: "Unit created.", level: "success" }; } }); }
  function openTaskModal() { openForm({ title: "New Quick Task", content: `<form class="samt-form" data-form="new-quick-task"><label>Name<input class="samt-input" name="name" required autofocus></label><div class="samt-form-grid"><label>Date<input class="samt-input" name="date" type="date"></label><label>Time<input class="samt-input" name="time" type="time"></label><label>Deadline<input class="samt-input" name="deadline" type="datetime-local"></label></div><button class="samt-button primary" type="submit">Create task</button></form>`, onSubmit: (form) => { const data = new FormData(form); engine.commands.createQuickTask({ name: data.get("name"), date: data.get("date") || null, time: data.get("time") || null, deadline: data.get("deadline") ? new Date(data.get("deadline")).toISOString() : null }); flash = { message: "Quick task created.", level: "success" }; } }); }
  function openReviewModal(id = null) { const state = stateForView(); const review = id ? state.reviews?.find((item) => item.id === id) : null; openForm({ title: review ? "Edit Review" : "New Review", content: `<form class="samt-form" data-form="review" data-id="${esc(id || "")}"><label>Name<input class="samt-input" name="name" value="${esc(review?.name || "")}" required autofocus></label><label>Date<input class="samt-input" name="date" type="date" value="${esc(review?.date || new Date().toISOString().slice(0, 10))}"></label><label>Notes<textarea class="samt-input" name="notes" rows="7">${esc(review?.notes || "")}</textarea></label><button class="samt-button primary" type="submit">${review ? "Save review" : "Create review"}</button></form>`, onSubmit: (form) => { const data = new FormData(form); if (id) engine.commands.updateReview(id, { name: data.get("name"), date: data.get("date"), notes: data.get("notes") }); else engine.commands.createReview({ name: data.get("name"), date: data.get("date"), notes: data.get("notes") }); flash = { message: "Review saved.", level: "success" }; } }); }
  function handleClick(event) {
    const target = event.target.closest?.("[data-action]"); if (!target) return; const action = target.dataset.action; const id = target.dataset.id;
    if (action === "open-log") return openLogModal(id, { occurrenceId: target.dataset.occurrenceId, blockId: target.dataset.blockId });
    if (action === "new-action") return openNewAction(); if (action === "new-block") return openNewBlock(target.dataset.type || "collection"); if (action === "add-result") return openResultModal(id); if (action === "edit-result") return openResultModal(target.dataset.actionId, id); if (action === "remove-result") { if (windowRef?.confirm && !windowRef.confirm("Remove this Result Field from future logs? Existing history is preserved.")) return; return runCommand(() => engine.commands.removeResultField(target.dataset.actionId, id), "Result Field removed."); } if (action === "add-relationship") return openRelationshipModal(id); if (action === "new-category") return openCategoryModal(); if (action === "new-tag") return openTagModal(); if (action === "new-unit") return openUnitModal(); if (action === "new-quick-task") return openTaskModal(); if (action === "new-review") return openReviewModal(); if (action === "edit-review") return openReviewModal(id);
    if (action === "archive-action") return runCommand(() => engine.commands.archiveAction(id), "Action archived."); if (action === "archive-category") return runCommand(() => engine.commands.archiveCategory(id), "Category archived."); if (action === "pause-block") return runCommand(() => engine.commands.pauseBlock(id), "Block paused."); if (action === "activate-block") return runCommand(() => engine.commands.activateBlock(id), "Block activated."); if (action === "remove-relationship") return runCommand(() => engine.commands.removeRelationship(target.dataset.blockId, id), "Relationship removed."); if (action === "complete-occurrence") return runCommand(() => engine.commands.completeOccurrence(id), "Occurrence completed."); if (action === "skip-occurrence") return runCommand(() => engine.commands.skipOccurrence(id), "Occurrence skipped."); if (action === "log-occurrence") { const occurrence = engine.getState().occurrences.find((item) => item.id === id); const relationship = engine.getState().blocks.flatMap((block) => block.relationships || []).find((candidate) => candidate.id === occurrence?.relationshipId); return openLogModal(relationship?.refId, { occurrenceId: id }); }
    if (action === "complete-task") return runCommand(() => target.dataset.kind === "quick" ? engine.commands.completeQuickTask(id) : engine.commands.completeTask(id), "Task completed."); if (action === "complete-review") return runCommand(() => engine.commands.completeReview(id), "Review completed."); if (action === "start-run") return runCommand(() => engine.commands.startRun({ blockId: id, label: "" }), "Run started."); if (action === "finish-run") return runCommand(() => engine.commands.finishRun(id), "Run finished."); if (action === "pause-run") return runCommand(() => engine.commands.pauseRun(id), "Run paused."); if (action === "resume-run") return runCommand(() => engine.commands.resumeRun(id), "Run resumed."); if (action === "advance-cycle") return runCommand(() => engine.commands.advanceCycle(id), "Cycle advanced."); if (action === "generate-small-cycle") return runCommand(() => engine.commands.generateCycleSmallCycle(id), "Small Cycle generated."); if (action === "set-primary-project") return runCommand(() => engine.commands.setPrimaryProject(id), "Primary Project selected."); if (action === "toggle-theme") { const current = documentRef.documentElement.dataset.theme || "light"; documentRef.documentElement.dataset.theme = current === "dark" ? "light" : "dark"; return; } if (action === "export") return downloadBackup(); if (action === "restore-import") return runCommand(() => engine.commands.restoreLastImport(), "Previous state restored.");
  }
  function downloadBackup() { const blob = new Blob([serializePackage(engine.getState())], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = documentRef.createElement("a"); anchor.href = url; anchor.download = `samt-v3-backup-${new Date().toISOString().slice(0, 10)}.json`; anchor.click(); windowRef?.setTimeout?.(() => URL.revokeObjectURL(url), 0); showFlash("Backup exported.", "success"); }
  function handleSubmit(event) {
    const form = event.target.closest?.("form[data-form]"); if (!form) return; event.preventDefault(); const data = new FormData(form); const kind = form.dataset.form;
    try {
      if (kind === "edit-action") { const id = form.dataset.id; engine.commands.updateAction(id, { name: data.get("name"), description: data.get("description"), direction: data.get("direction"), tagIds: data.getAll("tagId"), completion: data.get("completionMethod") === "quantity" ? { method: "quantity", target: Number(data.get("completionValue")) } : { method: "time", minimumMinutes: Number(data.get("completionValue")) } }); }
      else if (kind === "edit-block") { const id = form.dataset.id; const block = blockById(engine.getState(), id); engine.commands.updateBlock(id, { name: data.get("name"), description: data.get("description"), definitionStatus: data.get("definitionStatus"), config: { ...(block?.config || {}), ...blockConfigFromForm(form, block?.type) } }); }
      else if (kind === "settings") engine.commands.updateSettings({ timezone: data.get("timezone"), weekStartsOn: Number(data.get("weekStartsOn")), capacity: { availableMinutes: Math.max(0, Number(data.get("availableHours") || 0) * 60), periodDays: Math.max(1, Math.min(14, Number(data.get("periodDays") || 7))) }, defaults: { targetAutoClose: data.get("targetAutoClose") === "on", cycleAutoClose: data.get("cycleAutoClose") === "on", routineExpire: data.get("routineExpire") === "on", actionListExpire: data.get("actionListExpire") === "on" } });
      else if (kind === "analysis-filter") { const params = new URLSearchParams(); for (const name of ["blockId", "actionId", "from", "to"]) if (data.get(name)) params.set(name, data.get(name)); router.navigate(`/analysis?${params}`); return; }
      else if (kind === "import") return;
      flash = { message: "Saved.", level: "success" }; render();
    } catch (error) { const message = error?.message || "Could not save."; const target = form.querySelector("[data-form-error]"); if (target) target.textContent = message; else showFlash(message, "error"); }
  }
  function handleChange(event) { const input = event.target; if (input.matches?.("[data-file='import']")) { const file = input.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { engine.commands.importPackage(JSON.parse(String(reader.result))); flash = { message: "Backup imported atomically.", level: "success" }; render(); } catch (error) { showFlash(error?.message || "Import failed; original state is unchanged.", "error"); } }; reader.readAsText(file); } if (input.matches?.("[data-filter='action-search'], [data-filter='action-direction']")) { const params = new URLSearchParams(activeRoute.query); if (input.dataset.filter === "action-search") params.set("search", input.value); else params.set("direction", input.value); router.navigate(`/actions?${params}`); } }
  root.addEventListener("click", handleClick); root.addEventListener("submit", handleSubmit); root.addEventListener("change", handleChange); router.start(); return { router, render, modal };
}
